contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // The test exercises C.fallback by sending Ether via low-level call.
    // Inputs: amount to send and a fakeTimestampToggle to simulate two different block timestamps
    // (we cannot actually change block.timestamp, so we use two runs via different parameters
    // to characterize behavior; the property is general over the amount parameter).
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // Read before-state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Perform the call to fallback and catch revert
        bool reverted;
        (bool ok,) = address(c).call{value: amount}("0x");
        reverted = !ok;

        // Read after-state (fallback may have reverted, in which case state should be unchanged)
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule asserted:
        // - If the call reverted then pastBlockTime and balance are unchanged.
        // - If the call did not revert then amount must have been exactly 10 ether and
        //   pastBlockTime equals the current block.timestamp and either the contract
        //   paid out entire balance (so afterBal == 0) when block.number % 15 == 0,
        //   or otherwise afterBal == beforeBal + amount.
        assert(
            reverted
            ? (afterPast == beforePast && afterBal == beforeBal)
            : (
                // call succeeded
                // amount must be 10 ether
                amount == 10 ether
                // pastBlockTime updated to current block.timestamp
                && afterPast == block.timestamp
                // balance changed either by full payout when block.number%15==0 or increased by amount
                && (
                    (block.number % 15 == 0 && afterBal == 0)
                    || (block.number % 15 != 0 && afterBal == beforeBal + amount)
                )
            )
        );
    }

    // Allow receiving refunded Ether if needed
    receive() external payable {}
}

