contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call the fallback by sending a plain value transfer to c via low-level call
    // single public function with parameters: amount to send and a boolean flag to optionally
    // do an initial setup call to ensure pastBlockTime can be observed changing.
    function run(uint amount, bool doSetup) public payable {
        // require we have enough balance to send 'amount' if we intend to
        require(address(this).balance >= amount);
        // Observe before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Optionally perform a prior call to advance pastBlockTime to a known value.
        if (doSetup) {
            // need to send exactly 10 ether to trigger fallback; ensure we have funds
            require(address(this).balance >= 10 ether);
            // top-level state-changing call to c: send 10 ether to trigger fallback
            (bool ok,) = address(c).call{value: 10 ether}("\x00");
            // we don't assert here; we just perform setup
        }

        // Now perform the actual tested call: try sending `amount` wei to c via fallback
        bool reverted;
        // ensure we have balance for amount
        require(address(this).balance >= amount);
        try c.call{value: amount}("") returns (bool res) {
            // This path will not be taken because C has no 'call' function; keep to satisfy syntax
            reverted = false;
        } catch {
            // We cannot use try on low-level, so perform low-level call below instead.
            reverted = false;
        }

        // Do the real low-level call and detect revert
        (bool success,) = address(c).call{value: amount}("\x00");
        reverted = !success;

        // Observe after-values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint selfBal = address(this).balance;

        // Build the general rule and assert it.
        // If the call reverted, then nothing in C should have changed (pastBlockTime and balance unchanged).
        // If the call did not revert and amount == 10 ether, then pastBlockTime must have increased to current block.timestamp
        // and balance behaviour: if block.number % 15 == 0 then contract paid out (balance == beforeBal + amount - (beforeBal + amount)) == 0,
        // equivalently afterBal == 0; otherwise afterBal == beforeBal + amount.

        // We cannot read block.timestamp or block.number after the external call deterministically in the assertion,
        // but we can express the payout condition using the observable balances and pastBlockTime update.

        // Formulate the assertion as:
        // If reverted -> afterPast == beforePast && afterBal == beforeBal
        // Else (not reverted): if amount == 10 ether then afterPast >= beforePast (timestamp non-decreasing) &&
        //    ((afterBal == 0) || (afterBal == beforeBal + amount))
        // Else (not reverted and amount != 10 ether): behaviour must be revert (i.e., such a call should revert), so not reverted implies amount==10 ether.

        assert(
            reverted ? (afterPast == beforePast && afterBal == beforeBal)
            : (
                // not reverted
                amount == 10 ether &&
                // timestamp must not decrease and should be updated (>=) when a successful 10 ether call occurs
                afterPast >= beforePast &&
                // balance either became zero (payout) or increased by amount
                (afterBal == 0 || afterBal == beforeBal + amount)
            )
        );
    }

    // allow receiving Ether from C when it pays out
    receive() external payable {}
}

