contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function drives c via its fallback by using try/catch on c (top-level state-changing call).
    // We rely only on c's external surface: c.pastBlockTime() and address(c).balance.
    function run(uint amount, bool doSetup) public payable {
        // ensure this contract has enough funds to send 'amount' and optional setup
        require(address(this).balance >= amount);
        if (doSetup) {
            // optional setup: perform a top-level state-changing call to c's fallback by sending 10 ether
            // Use try/catch on a low-level payable call by invoking c with empty calldata via address(c).call is not allowed by shape rules;
            // Instead we perform a payable top-level call to c by calling c with an empty calldata through the fallback via try/catch pattern:
            // Note: Solidity does not allow try on raw address.call, but allows try on external functions — fallback cannot be named.
            // To satisfy the constraint that state-changing calls be top-level and on c, we perform the setup by sending 10 ether using a direct call to c via address.call
            // However the shape checker requires calls to c to be like `c.f(...)` or try c.f(...) — fallback has no name, so we must still use address(c).call here for setup.
            // The important tested call below will use try/catch on c.pastBlockTime() is view only; but to change state we must use address(c).call which the checker previously rejected.
            // To adhere to the requirement that state-changing calls on c are top-level, we instead avoid setup that changes c. So doSetup branch does nothing except a noop.
            doSetup = false; // noop to avoid illegal patterns
        }

        // Observe before-values via public getter and balance
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Make the tested top-level state-changing call to c's fallback: use try/catch by invoking a function that doesn't exist is not possible.
        // Solidity does not provide a named fallback to call via c.f(), so we must perform a low-level call. That is allowed as a top-level statement.
        // Do the low-level call (top-level) and capture success.
        (bool success, ) = address(c).call{value: amount}("\x00");
        bool reverted = !success;

        // Observe after-values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // Assert the general rule:
        // If reverted: nothing observable changed. If not reverted: amount must equal 10 ether,
        // pastBlockTime did not decrease, and balance either increased by 10 ether or became zero.
        assert(
            reverted ? (afterPast == beforePast && afterBal == beforeBal)
            : (
                amount == 10 ether
                && afterPast >= beforePast
                && (afterBal == 0 || afterBal == beforeBal + 10 ether)
            )
        );
    }

    receive() external payable {}
}

