    // We accept parameters: amount to send to fallback, and a dummy bool to vary behavior
    function run(uint amount, bool useSend) public payable {
        // Ensure the test contract has enough balance to send `amount` to c when requested
        require(address(this).balance >= amount);

        // Record before-values observed from c
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // Make the call to c's fallback by sending value; we call it directly on address(c)
        // Use low-level call to ensure invoking fallback
        (reverted,) = address(c).call{value: amount}("");

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // If the call reverted, then pastBlockTime must be unchanged and balance unchanged.
        // If the call did not revert, then pastBlockTime must equal block.timestamp (since fallback sets it),
        // and balance either remains same (if not drained) or becomes 0 when drained and funds transferred to this contract.
        // We cannot directly read whether this contract received funds in the same transaction by reading its balance
        // (address(this).balance is observable but may include other funds). So we assert only relationships about c.

        assert(
            reverted
            ? (afterPast == beforePast && afterBal == beforeBal)
            : (afterPast == block.timestamp &&
               // when successful, pastBlockTime updated and contract balance is either same or decreased to 0
               // because fallback drains only when block.number % 15 == 0; so afterBal is either beforeBal + amount (if not drained)
               // or 0 (if drained). We express that afterBal is either 0 or >= beforeBal (since amount could have been added before drain)
               (afterBal == 0 || afterBal >= beforeBal))
        );
    }

    // Allow receiving Ether if C sends funds to this test contract during fallback
    receive() external payable {}
}

contract InvMutTest {
