    constructor(C _c) { c = _c; }

    // We implement the test in one public payable function.
    // Parameters:
    //  - amount: the Ether forwarded to c in the fallback call
    //  - newTime: a value that we require to be strictly greater than the observed pastBlockTime when we expect the call to succeed
    // The function will try the call and then assert a general invariant about behavior.
